def seed_data(db: Session) -> None:
    product_ids = [entry[0] for entry in SAMPLE_PRODUCTS]
    existing_products = {
        product.id: product
        for product in db.scalars(select(Product).where(Product.id.in_(product_ids)))
    }
    products = []
    updated = False
    for order, entry in enumerate(SAMPLE_PRODUCTS, start=1):
        product_id, name, maker, seller, category, price, cost, image, stock, age, _sample_offers, description, story, tags = entry
        existing = existing_products.get(product_id)
        if existing is not None:
            if existing.owner_id is None:
                if not existing.offers:
                    existing.offers = True
                    updated = True
                if existing.name != name:
                    existing.name = name
                    updated = True
                if existing.image != image:
                    existing.image = image
                    updated = True
                if existing.tags != tags:
                    existing.tags = tags
                    updated = True
            continue
        products.append(Product(
            id=product_id, name=name, maker=maker, seller=seller, category=category,
            price=price, cost=cost, image=image, stock_qty=stock, age=age,
            available=stock > 0, offers=True, description=description, story=story,
            tags=tags, added_order=len(SAMPLE_PRODUCTS) - order + 1,
        ))
    if products or updated:
        db.add_all(products)
        db.commit()
